      profileActive,
      profileText,
      recordTextureLoaded,
      profileFlourishLoaded,
      profileTitlePlaqueLoaded,
      profileStatChipFrameLoaded,
      profileRecordRowFrameLoaded,
      profileSectionTabFrameLoaded,
      profileProgressRailFrameLoaded,
